// One-shot migration extractor: AI Players Add-On -> Verdant core/data.
//
// Reads the AI Players sources (Gamemode One, kept in-repo until the migration
// completes) and emits the compact, engine-free data modules under
// scripts/core/data/. Everything it writes is *data*: no class scaffolding, no
// source maps, no @minecraft imports.
//
//   node tools/migrate/extract-aiplayers.mjs "<path to AI Players BP>/scripts"
//
// The sources are removed from the repo once this has run (docs/MIGRATION.md
// records the provenance, the source commit and what was deliberately left out).
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

const repo = fileURLToPath(new URL("../../", import.meta.url));
const out = join(repo, "scripts", "core", "data");
const srcRoot = process.argv[2];
if (!srcRoot) {
    console.error('usage: node tools/migrate/extract-aiplayers.mjs "<AI Players BP>/scripts"');
    process.exit(2);
}

const TICKS_PER_SECOND = 20;

/** Strip the base64 sourcemap trailer and leading file comments. */
function read(file) {
    return readFileSync(join(srcRoot, file), "utf8")
        .replace(/\/\/# sourceMappingURL=[^\n]*/g, "")
        .replace(/\/\* eslint[^\n]*\n/g, "");
}

/**
 * Find `Class.Property = <expression>;` and evaluate the expression.
 * A tiny scanner keeps brace/string/comment state so nested objects with
 * strings containing braces survive.
 */
function lift(text, property) {
    const anchor = text.indexOf(`${property} = `);
    if (anchor === -1)
        throw new Error(`property ${property} not found`);
    let i = text.indexOf("=", anchor) + 1;
    while (/\s/.test(text[i])) i++;
    const start = i;
    let depth = 0, inString = null, escape = false, lineComment = false, blockComment = false;
    for (; i < text.length; i++) {
        const c = text[i];
        if (lineComment) { if (c === "\n") lineComment = false; continue; }
        if (blockComment) { if (c === "*" && text[i + 1] === "/") { blockComment = false; i++; } continue; }
        if (inString) {
            if (escape) { escape = false; continue; }
            if (c === "\\") { escape = true; continue; }
            if (c === inString) inString = null;
            continue;
        }
        if (c === "/" && text[i + 1] === "/") { lineComment = true; i++; continue; }
        if (c === "/" && text[i + 1] === "*") { blockComment = true; i++; continue; }
        if (c === '"' || c === "'" || c === "`") { inString = c; continue; }
        if (c === "{" || c === "[" || c === "(") depth++;
        else if (c === "}" || c === "]" || c === ")") depth--;
        else if ((c === ";" || c === "\n") && depth <= 0) break;
    }
    const expr = text.slice(start, i).trim().replace(/;$/, "");
    // eslint-disable-next-line no-new-func
    return new Function("TicksPerSecond", `return (${expr});`)(TICKS_PER_SECOND);
}

/** JSON with one entry per line - readable diffs, no scaffolding. */
function json(value, indent = 0) {
    const pad = " ".repeat(indent);
    if (Array.isArray(value))
        return `[${value.map((v) => json(v, indent)).join(", ")}]`;
    if (value && typeof value === "object") {
        const entries = Object.entries(value).map(([k, v]) => `${JSON.stringify(k)}: ${json(v, indent + 4)}`);
        if (entries.join("").length < 100)
            return `{ ${entries.join(", ")} }`;
        return `{\n${entries.map((e) => pad + "    " + e).join(",\n")}\n${pad}}`;
    }
    return JSON.stringify(value);
}

const header = (title, sources, note) => `// ${title}
//
// MIGRATED DATA - generated by tools/migrate/extract-aiplayers.mjs from the
// AI Players Add-On (Gamemode One) that previously lived in this repo:
${sources.map((s) => `//   ${s}`).join("\n")}
// The original generator for the upstream pack was its own build; this is a
// straight lift of the tables plus the notes below. See docs/MIGRATION.md.
//
// ${note}
//
// Engine-free by construction: data only, no @minecraft imports.

`;

mkdirSync(out, { recursive: true });

// ---------------------------------------------------------------- hardness
const hardnessSrc = read("Data/BlockHardnessData.js");
const hardness = lift(hardnessSrc, "BlockHardnessData.Hardness");
const hardnessKeys = Object.keys(hardness).sort();
writeFileSync(join(out, "hardness.js"), header(
    "Block hardness table (vanilla, Bedrock 1.21)",
    ["Data/BlockHardnessData.js", "https://minecraft.wiki/w/Breaking#Blocks_by_hardness"],
    "A value of -1 means indestructible (bedrock, barrier, portals). Blocks that are\n// absent are treated as instant-break (hardness 0).",
) + `export const HARDNESS = {\n` +
    hardnessKeys.map((k) => `    ${JSON.stringify(k)}: ${hardness[k]},`).join("\n") +
    `\n};\n\nexport const DEFAULT_HARDNESS = 0;\n\nexport function hardnessOf(typeId) {\n    const h = HARDNESS[typeId];\n    return h === undefined ? DEFAULT_HARDNESS : h;\n}\n`);

// ---------------------------------------------------------------- mining rules
const miningSrc = read("Data/BlockMiningData.js");
const pickaxeExemptions = lift(miningSrc, "BlockMiningData.PickaxeExemptions");
const restrictedBlocks = lift(miningSrc, "BlockMiningData.RestrictedBlocks");
const blockValidityMap = lift(miningSrc, "BlockMiningData.BlockValidityMap");
const placementSrc = read("Data/BlockPlacementData.js");
const overrideable = lift(placementSrc, "BlockPlacementData.OverrideableBlocks");

const setOf = (name, values, note) =>
    `/** ${note} */\nexport const ${name} = new Set(${json([...values].sort(), 4)});\n\n`;
writeFileSync(join(out, "block-rules.js"), header(
    "Block rules: what may be broken, what may be replaced",
    ["Data/BlockMiningData.js", "Data/BlockPlacementData.js"],
    "RESTRICTED_BLOCKS is the safety list: an autonomous bot must not dismantle\n// containers, beds, workstations or spawners it may later need (and must never\n// break a player's storage). PICKAXE_EXEMPT blocks are pickaxe-speeded but\n// harvestable bare-handed. VALIDITY_MAP folds lit/unlit variants into one id for\n// scan planning. OVERRIDEABLE_BLOCKS may be replaced when placing a block.",
) +
    setOf("PICKAXE_EXEMPT", pickaxeExemptions, "Pickaxe-speeded blocks that still drop without a pickaxe.") +
    setOf("RESTRICTED_BLOCKS", restrictedBlocks, "Blocks the bot refuses to break.") +
    `/** Block variants that are the same target while mining (redstone ore lights up). */\nexport const VALIDITY_MAP = ${json(blockValidityMap, 4)};\n\n` +
    setOf("OVERRIDEABLE_BLOCKS", overrideable, "Blocks a new block may be placed into (vegetation, fluids, fire).") +
    `/** Fold lit/unlit variants so a plan does not lose its target mid-dig. */\nexport function canonicalBlock(typeId) {\n    return VALIDITY_MAP[typeId] ?? typeId;\n}\n\nexport function isRestricted(typeId) {\n    return RESTRICTED_BLOCKS.has(canonicalBlock(typeId));\n}\n\nexport function isOverrideable(typeId) {\n    return OVERRIDEABLE_BLOCKS.has(typeId);\n}\n`);

// ---------------------------------------------------------------- recipes
const craftSrc = read("Data/CraftingTreeData.js");
const recipes = lift(craftSrc, "CraftingTreeData.Recipes");
const smeltMap = lift(craftSrc, "CraftingTreeData.RawMaterialToSmeltedMaterialMap");
const woodFamilies = lift(craftSrc, "CraftingTreeData.WoodFamilies");
const stoneFamily = lift(craftSrc, "CraftingTreeData.StoneFamily");
// The upstream TagResolutions/IngredientToResult tables are derived from the
// wood/stone families above, so they are rebuilt here rather than lifted (the
// upstream literals call back into CraftingTreeData at class-init time).
const logVariants = (family) => [family.log, family.strippedLog, family.wood, family.strippedWood].filter(Boolean);
const tagResolutions = {
    "family:logs": woodFamilies.flatMap(logVariants),
    "family:planks": woodFamilies.map((f) => f.planks),
    "family:stone": stoneFamily,
};
const ingredientToResult = Object.fromEntries(
    woodFamilies.flatMap((f) => logVariants(f).map((v) => [v, f.planks])),
);

// Normalise a recipe to a small, stable shape: { out, n, in, table }
const compactRecipes = recipes.map((r) => ({
    out: r.result.id,
    n: r.result.amount,
    in: r.ingredients.map((i) => [i.id, i.amount]),
    table: !!r.requiresCraftingTable,
}));
const byOutput = {};
for (const r of compactRecipes) (byOutput[r.out] ??= []).push(r);

writeFileSync(join(out, "recipes.js"), header(
    "Crafting + smelting graph",
    ["Data/CraftingTreeData.js", "Helpers/CraftingHelper.js"],
    "Recipes are keyed by output id, ingredients are [id, amount] pairs. Family\n// ingredients use `family:<name>` (e.g. family:planks) and resolve through\n// TAG_RESOLUTIONS; INGREDIENT_TO_RESULT maps a concrete ingredient to the\n// concrete result (oak_planks -> oak_door). Recipes with `table: true` need a\n// crafting table nearby.",
) +
    `/** @typedef {{ out: string, n: number, in: Array<[string, number]>, table: boolean }} Recipe */\n\n` +
    `/** All recipes, migration order preserved. */\nexport const RECIPE_LIST = ${json(compactRecipes, 4)};\n\n` +
    `/** Recipes by output id. */\nexport const RECIPES_BY_OUTPUT = ${json(byOutput, 4)};\n\n` +
    `/** family:<name> -> concrete item ids that satisfy it. */\nexport const TAG_RESOLUTIONS = ${json(tagResolutions, 4)};\n\n` +
    `/** Concrete ingredient -> concrete result (wood species mapping). */\nexport const INGREDIENT_TO_RESULT = ${json(ingredientToResult, 4)};\n\n` +
    `/** Raw material -> smelted result. */\nexport const SMELT_MAP = ${json(smeltMap, 4)};\n\n` +
    `/** Wood species families: log/stripped log/wood/stripped wood/planks. */\nexport const WOOD_FAMILIES = ${json(woodFamilies, 4)};\n\n` +
    `/** Stone variants interchangeable in recipes. */\nexport const STONE_FAMILY = ${json(stoneFamily.sort(), 4)};\n`);

// ---------------------------------------------------------------- item values
let itemValues = {};
try {
    const invSrc = read("Data/InventoryData.js");
    itemValues = lift(invSrc, "InventoryData.ExactItemValues");
}
catch (e) {
    console.warn("item values skipped:", String(e));
}
writeFileSync(join(out, "item-values.js"), header(
    "Item value table (keep/drop scoring)",
    ["Data/InventoryData.js"],
    "Used by inventory triage: what to keep when the bag is full and what is junk.\n// Values are relative weights, not prices.",
) + `export const ITEM_VALUES = ${json(itemValues, 4)};\n\nexport function itemValue(typeId) {\n    return ITEM_VALUES[typeId] ?? 0;\n}\n`);

console.log("migrated data written to scripts/core/data/");
console.log(`  hardness:      ${hardnessKeys.length} entries`);
console.log(`  restricted:    ${restrictedBlocks.size} blocks`);
console.log(`  overrideable:  ${overrideable.size} blocks`);
console.log(`  recipes:       ${compactRecipes.length} (${Object.keys(byOutput).length} outputs)`);
console.log(`  tag families:  ${Object.keys(tagResolutions).length}`);
console.log(`  item values:   ${Object.keys(itemValues).length}`);
